import base64
import json
import os
from pathlib import Path
import runpy
import subprocess
import sys

from kaggle_secrets import UserSecretsClient

user_secrets = UserSecretsClient()
for secret_name in ("HF_TOKEN", "WANDB_API_KEY"):
    secret_value = user_secrets.get_secret(secret_name)
    if not secret_value:
        raise RuntimeError(f"required Kaggle secret is unavailable: {secret_name}")
    os.environ[secret_name] = secret_value

subprocess.run(
    [
        sys.executable,
        "-m",
        "pip",
        "install",
        "--disable-pip-version-check",
        "--no-input",
        *['trl==1.8.0', 'transformers==5.13.1', 'datasets==4.8.5', 'peft==0.19.1', 'torchao==0.17.0', 'wandb==0.28.0'],
    ],
    check=True,
)

FILES = json.loads("{\"remote_preflight.py\": \"\", \"contrast_sampler.py\": \"\", \"trl_sampler_adapter.py\": \"\"}")
SCRIPT_ARGS = json.loads("[\"--task\", \"gsm8k\", \"--arm\", \"contrast_early_stop_g2_to_g8\", \"--seed\", \"211\", \"--unit-fingerprint\", \"fee1214d2061c239d615d7d3a752aa39e7cbaccee4dc5ddd60f02107d667d0f5\", \"--stack-fingerprint\", \"24541e75a5a40186261dd1006a8e45376e6d3665e2745cecaf0e99177aff1899\", \"--source-commit\", \"2810490e4f163a2c0e032766a58596f5ea2b7498\", \"--protocol-sha256\", \"47a3e4f36b0d028e65f7fbe781de1033819f58823fa9039eb1615c742abe3455\", \"--provider\", \"kaggle\", \"--hardware-flavor\", \"NvidiaTeslaA100\", \"--hf-repo\", \"arvindcr4/tinker-rl-next-preflight-kaggle-gsm8k-contrast_ear-s211-fee1214d\", \"--wandb-project\", \"tinker-rl-lab\", \"--wandb-group\", \"next-submission-preflight-kaggle\", \"--wandb-run-name\", \"next-preflight-kaggle-gsm8k-contrast_early_stop_g2_to_g8-s211-fee1214d\"]")
source_root = Path("/kaggle/working/next-submission-preflight-source")
source_root.mkdir(parents=True, exist_ok=True)
for name, payload in FILES.items():
    (source_root / name).write_bytes(base64.b64decode(payload))
os.environ["NEXT_PREFLIGHT_SOURCE_ROOT"] = str(source_root)
os.environ["NEXT_PREFLIGHT_OUTPUT_DIR"] = "/kaggle/working/next-preflight-output"
os.environ["NEXT_PREFLIGHT_RESULT_PATH"] = "/kaggle/working/next_preflight_result.json"
os.environ["NEXT_PREFLIGHT_REPORT_TO"] = "wandb"
sys.path.insert(0, str(source_root))
script = source_root / "remote_preflight.py"
sys.argv = [str(script), *SCRIPT_ARGS]
runpy.run_path(str(script), run_name="__main__")
